        int minor_col = 0;
        for (int j = 0; j < 3; ++j) {
            if (j == col) continue;
            minor[minor_row][minor_col] = m[i][j];
            ++minor_col;
        }
        ++minor_row;
    }

    // Calculate the determinant of the 2x2 minor matrix
    double det = minor[0][0] * minor[1][1] - minor[0][1] * minor[1][0];

    // Apply the cofactor sign: (-1)^(row + col)
    return ((row + col) % 2 == 0) ? det : -det;
